{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Invalid budget')
    alloc = [s['minimum'] for s in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i, s in enumerate(segments):
            if alloc[i] >= s['capacity']:
                continue
            ratio = s['importance'] / (alloc[i] + 1.0)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx is None:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(len(segments))}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
